import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";

/** Versioned, provider-neutral owner boundary. A PR is not a hosting or CI grant. */
export const PULL_REQUEST_CONTRACT_VERSION = 1;

export interface PullRequestRef {
  repository: RepositoryIdentity;
  ref: string;
  revision: string;
}

export interface PullRequestReview {
  nativeId: string;
  actor: { nativeId: string; login: string; kind: "human" | "bot" | "unknown" };
  decision: "approved" | "changes_requested" | "commented" | "pending";
  headRevision: string;
  dismissed: boolean;
  stale: boolean;
  submittedAt: string;
}

export interface PullRequestObservation {
  repository: RepositoryIdentity;
  nativeId: string;
  head: PullRequestRef;
  base: PullRequestRef;
  state: "open" | "closed" | "merged";
  draft: boolean;
  mergeable: boolean | null;
  mergeStrategy: "fast-forward-only" | "other" | "unknown";
  requiredChecks: Array<{ context: string; state: "success" | "failure" | "pending" | "unknown" }>;
  advisoryChecks?: Array<{ context: string; state: "success" | "failure" | "pending" | "unknown" }>;
  queuedMerge?: "none" | "queued" | "unknown";
  requiredApprovals: number;
  reviews: PullRequestReview[];
  discussionCount: number;
  /** Provider-native update or conflict token. It cannot substitute for head identity. */
  providerRevision: string;
  mergedRevision?: string;
  url?: string;
}

export interface PullRequestAdapter {
  read(repository: RepositoryIdentity, nativeId: string): Promise<PullRequestObservation | null>;
  mergeFastForward(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<void>;
}

export interface ExactMergeRequest {
  repository: RepositoryIdentity;
  nativeId: string;
  headRevision: string;
  baseRef: string;
  baseRevision: string;
  strategy: "fast-forward-only";
  requiredHumanActorId: string;
}

export class PullRequestError extends Error {
  override readonly name = "PullRequestError";
  constructor(readonly code: string) { super(code); }
}

/** The owner must persist merge intent before calling this function. */
export async function requestExactMerge(adapter: PullRequestAdapter, request: ExactMergeRequest): Promise<PullRequestObservation> {
  if (!request.nativeId || request.nativeId.length > 256 || !validRevision(request.headRevision) ||
      !validBranchRef(request.baseRef) || !validRevision(request.baseRevision) ||
      !request.requiredHumanActorId) throw new PullRequestError("invalid_merge_request");
  const before = await adapter.read(request.repository, request.nativeId);
  if (!before) throw new PullRequestError("pr_missing");
  validateObservation(before, request.repository, request.nativeId);
  if (before.state === "merged") {
    if (before.head.revision === request.headRevision && before.mergedRevision === request.headRevision) return before;
    throw new PullRequestError("merge_identity_mismatch");
  }
  if (before.state !== "open") throw new PullRequestError("pr_closed");
  if (before.draft) throw new PullRequestError("draft_pr");
  if (before.queuedMerge === "queued") throw new PullRequestError("merge_already_queued");
  if (before.head.revision !== request.headRevision) throw new PullRequestError("head_moved");
  if (before.base.ref !== request.baseRef || before.base.revision !== request.baseRevision) {
    throw new PullRequestError("base_moved");
  }
  if (before.mergeStrategy !== request.strategy) throw new PullRequestError("strategy_unsupported");
  if (before.mergeable !== true) throw new PullRequestError(before.mergeable === false ? "merge_conflict" : "mergeability_unknown");
  if (before.requiredChecks.some((check) => check.state !== "success")) throw new PullRequestError("required_checks_incomplete");
  const approvals = new Map<string, PullRequestReview>();
  for (const review of before.reviews) {
    if (review.actor.kind !== "human") continue;
    const previous = approvals.get(review.actor.nativeId);
    if (previous && review.submittedAt === previous.submittedAt && review.nativeId !== previous.nativeId) {
      throw new PullRequestError("approval_ambiguous");
    }
    if (!previous || Date.parse(review.submittedAt) > Date.parse(previous.submittedAt)) {
      approvals.set(review.actor.nativeId, review);
    }
  }
  const current = [...approvals.values()].filter((review) => !review.dismissed && !review.stale &&
    review.headRevision === request.headRevision);
  if (approvals.get(request.requiredHumanActorId)?.decision !== "approved" ||
      !current.some((review) => review.actor.nativeId === request.requiredHumanActorId && review.decision === "approved") ||
      current.filter((review) => review.decision === "approved").length < before.requiredApprovals ||
      current.some((review) => review.decision === "changes_requested")) {
    throw new PullRequestError("approval_missing");
  }
  try { await adapter.mergeFastForward(request.repository, request.nativeId, request.headRevision); }
  catch { /* The provider may have committed the effect before the error. Reconcile by read. */ }
  let after: PullRequestObservation | null;
  try { after = await adapter.read(request.repository, request.nativeId); }
  catch { throw new PullRequestError("merge_outcome_unknown"); }
  if (!after) throw new PullRequestError("merge_outcome_unknown");
  validateObservation(after, request.repository, request.nativeId);
  if (after.state === "merged" && after.head.revision === request.headRevision &&
      after.mergedRevision === request.headRevision) return after;
  throw new PullRequestError("merge_outcome_unknown");
}

export function validateObservation(value: PullRequestObservation, repository: RepositoryIdentity, nativeId: string): void {
  if (!sameRepository(value.repository, repository) || value.nativeId !== nativeId ||
      !sameRepository(value.head.repository, repository) || !sameRepository(value.base.repository, repository) ||
      !validBranchRef(value.head.ref) || !validBranchRef(value.base.ref) ||
      !validRevision(value.head.revision) || !validRevision(value.base.revision) ||
      !value.providerRevision || value.providerRevision.length > 256 ||
      (value.mergedRevision !== undefined && !validRevision(value.mergedRevision))) {
    throw new PullRequestError("invalid_provider_observation");
  }
}

