import { test } from "vitest";
import assert from "node:assert/strict";
import Database from "better-sqlite3";
import { PullRequestMergeStore } from "./mergeStore.js";
import { PullRequestMergeCoordinator } from "./mergeCoordinator.js";
import { PullRequestError, type PullRequestObservation } from "./contract.js";

const sha = "a".repeat(40);
const repository = { provider: "other", instanceId: "fixture", nativeId: "opaque/repo" };
const base: PullRequestObservation = { repository, nativeId: "pr-7",
  head: { repository, ref: "refs/heads/work", revision: sha },
  base: { repository, ref: "refs/heads/main", revision: "b".repeat(40) },
  state: "open", draft: false, mergeable: true, mergeStrategy: "fast-forward-only",
  requiredChecks: [], requiredApprovals: 1, reviews: [{ nativeId: "review-1",
    actor: { nativeId: "person-1", login: "human", kind: "human" }, decision: "approved",
    headRevision: sha, dismissed: false, stale: false, submittedAt: "2026-10-13T00:00:00Z" }],
  discussionCount: 0, providerRevision: "revision-1" };

test("merge intent precedes dispatch and uncertain retries only observe", async () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_merge_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, decision_id TEXT, actor_id TEXT, state TEXT, merged_revision TEXT,
    recorded_at TEXT, updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const effects = new PullRequestMergeStore(sqlite);
    let current = base;
    let dispatched = 0;
    const coordinator = new PullRequestMergeCoordinator({ effects, verifyAuthority: async () => {},
      adapter: { read: async () => current, mergeFastForward: async () => {
        assert.equal(effects.get("effect-1")?.state, "pending");
        dispatched++;
        throw new Error("timeout");
      } }, now: () => "2026-10-13T00:00:00Z", effectId: () => "effect-1" });
    const request = { bindingId: "pr", bindingRevision: 1, repository, nativePrId: "pr-7",
      headRevision: sha, baseRef: "refs/heads/main", baseRevision: "b".repeat(40),
      decisionId: "decision-1", actorId: "person-1" };
    await assert.rejects(coordinator.merge(request), (error: unknown) =>
      error instanceof PullRequestError && error.code === "merge_outcome_unknown");
    assert.equal(effects.get("effect-1")?.state, "unknown");
    await assert.rejects(coordinator.merge(request), (error: unknown) =>
      error instanceof PullRequestError && error.code === "merge_outcome_unknown");
    assert.equal(dispatched, 1);
    current = { ...base, state: "merged", mergedRevision: sha };
    assert.equal((await coordinator.merge(request)).state, "confirmed");
    assert.equal(dispatched, 1);
  } finally { sqlite.close(); }
});

test("a concurrent merge admission does not dispatch a second provider merge", async () => {
  const sqlite = new Database(":memory:");
  sqlite.exec(`CREATE TABLE pr_merge_effect (effect_id TEXT PRIMARY KEY, binding_id TEXT,
    binding_revision INTEGER, repository_key TEXT, native_pr_id TEXT, head_revision TEXT,
    base_ref TEXT, base_revision TEXT, decision_id TEXT, actor_id TEXT, state TEXT, merged_revision TEXT,
    recorded_at TEXT, updated_at TEXT, UNIQUE(binding_id,native_pr_id,head_revision));`);
  try {
    const effects = new PullRequestMergeStore(sqlite);
    const admit = effects.admit.bind(effects);
    effects.admit = (input) => {
      admit({ ...input, effectId: "winner" });
      return admit(input);
    };
    let merges = 0;
    const coordinator = new PullRequestMergeCoordinator({ effects, verifyAuthority: async () => {},
      adapter: { read: async () => base, mergeFastForward: async () => { merges++; } },
      now: () => "2026-10-13T00:00:00Z", effectId: () => "loser" });
    await assert.rejects(coordinator.merge({ bindingId: "pr", bindingRevision: 1, repository,
      nativePrId: "pr-7", headRevision: sha, baseRef: "refs/heads/main", baseRevision: "b".repeat(40),
      decisionId: "decision-1", actorId: "person-1" }), (error: unknown) =>
      error instanceof PullRequestError && error.code === "merge_outcome_unknown");
    assert.equal(merges, 0);
    assert.equal(effects.getByCandidate("pr", "pr-7", sha)?.effectId, "winner");
  } finally { sqlite.close(); }
});

