  const matches = data.filter((item: unknown) => {
    const pull = object(item, "malformed_pr_list");
    const head = object(pull.head, "malformed_pr_list");
    const base = object(pull.base, "malformed_pr_list");
    return sameNativeRepository(head.repo, repository) && sameNativeRepository(base.repo, repository) &&
      head.ref === headRef.slice(11) && base.ref === baseRef.slice(11);
  });
  if (matches.length > 1) throw new PullRequestError("ambiguous_pr_identity");
  if (!matches.length) return null;
  const number = object(matches[0], "malformed_pr_list").number;
  if (!Number.isSafeInteger(number) || Number(number) < 1) throw new PullRequestError("malformed_pr_list");
  return this.read(repository, String(number));
}

/** Caller persists the effect ID and exact branch identity before dispatch. */
async createDraft(repository: RepositoryIdentity, headRef: string, baseRef: string,
  headRevision: string, title: string): Promise<PullRequestObservation> {
  if (!validBranchRef(headRef) || !validBranchRef(baseRef) || !validRevision(headRevision) ||
      !title.trim() || title.length > 240) throw new PullRequestError("invalid_create_request");
  const existing = await this.findByBranches(repository, headRef, baseRef);
  if (existing) {
    if (existing.head.revision !== headRevision) throw new PullRequestError("head_moved");
    return existing;
  }
  const observed = await this.hosting.branch(repository, headRef).catch((error: unknown) => { throw translateHosting(error); });
  if (observed?.revision !== headRevision) throw new PullRequestError("head_moved");
  const draftTitle = /^\s*(?:WIP:|\[WIP\])/iu.test(title) ? title : `WIP: ${title}`;
  try {
    await this.request("POST", "/pulls", { head: headRef.slice(11), base: baseRef.slice(11), title: draftTitle });
  } catch (error) {
    // A timeout can follow successful creation; only an exact provider read resolves it.
    const found = await this.findByBranches(repository, headRef, baseRef).catch(() => null);
    if (found?.head.revision === headRevision && found.draft) return found;
    if (error instanceof PullRequestError && error.code === "permission_denied") throw error;
    throw new PullRequestError("create_outcome_unknown");
  }
  const created = await this.findByBranches(repository, headRef, baseRef).catch(() => null);
  if (!created || !created.draft || created.head.revision !== headRevision) throw new PullRequestError("create_outcome_unknown");
  return created;
}

/** The owner merge path may advance a draft by removing its WIP prefix. */
async markReady(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<PullRequestObservation> {
  const before = await this.read(repository, nativeId);
  if (!before || before.state !== "open" || before.head.revision !== exactHead) throw new PullRequestError("head_moved");
  if (!before.draft) return before;
  const raw = object(await this.request("GET", `/pulls/${nativeIndex(nativeId)}`), "malformed_pr");
  if (typeof raw.title !== "string" || !/^\s*(?:WIP:|\[WIP\])/iu.test(raw.title)) {
    throw new PullRequestError("draft_transition_unsupported");
  }
  const title = raw.title.replace(/^\s*(?:WIP:|\[WIP\])\s*/iu, "");
  try { await this.request("PATCH", `/pulls/${nativeIndex(nativeId)}`, { title }); }
  catch { /* Reconcile a write whose response was lost. */ }
  const after = await this.read(repository, nativeId).catch(() => null);
  if (!after || after.draft || after.head.revision !== exactHead) throw new PullRequestError("ready_outcome_unknown");
  return after;
}

async mergeFastForward(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<void> {
  await this.checkRepository(repository);
  if (!validRevision(exactHead)) throw new PullRequestError("invalid_merge_request");
  await this.request("POST", `/pulls/${nativeIndex(nativeId)}/merge`, { do: "fast-forward-only",
    head_commit_id: exactHead, force_merge: false, merge_when_checks_succeed: false,
    delete_branch_after_merge: false });
}

private async checkRepository(repository: RepositoryIdentity): Promise<void> {
  if (!sameRepository(await this.repository(), repository)) throw new PullRequestError("repository_mismatch");
}

private async readReviews(index: number): Promise<PullRequestReview[]> {
  const data = await this.request("GET", `/pulls/${index}/reviews?limit=100&page=1`);
  if (!Array.isArray(data) || data.length >= 100) throw new PullRequestError("review_observation_incomplete");
  return data.map((item: unknown) => {
    const review = object(item, "malformed_review");
    const user = object(review.user, "malformed_review");
    const decision = review.state === "APPROVED" ? "approved" : review.state === "REQUEST_CHANGES"
      ? "changes_requested" : review.state === "COMMENT" ? "commented" : "pending";
    const formal = decision === "approved" || decision === "changes_requested";
    if (!Number.isSafeInteger(review.id) || Number(review.id) < 1 || !Number.isSafeInteger(user.id) ||
        Number(user.id) < 1 || typeof user.login !== "string" || user.login.length > 128 ||
        typeof review.dismissed !== "boolean" || typeof review.stale !== "boolean" ||
        (formal && (typeof review.commit_id !== "string" || !validRevision(review.commit_id) ||
          typeof review.submitted_at !== "string" || !Number.isFinite(Date.parse(review.submitted_at))))) {
      throw new PullRequestError("malformed_review");
    }
    return { nativeId: String(review.id), actor: { nativeId: String(user.id), login: user.login,
      kind: user.type === "User" ? "human" as const : user.type === "Bot" ? "bot" as const : "unknown" as const },
      decision, headRevision: typeof review.commit_id === "string" && validRevision(review.commit_id) ? review.commit_id : "",
      dismissed: review.dismissed, stale: review.stale || !formal,
      submittedAt: typeof review.submitted_at === "string" && Number.isFinite(Date.parse(review.submitted_at))
        ? review.submitted_at : "" };
  });
}

private async readChecks(sha: string, contexts: string[]): Promise<{
  required: PullRequestObservation["requiredChecks"];
  advisory: NonNullable<PullRequestObservation["advisoryChecks"]>;
}> {
  const data = object(await this.request("GET", `/commits/${sha}/status?limit=100&page=1`), "malformed_status");
  if (data.sha !== sha || !Array.isArray(data.statuses) || data.statuses.length >= 100 ||
      !Number.isSafeInteger(data.total_count) || Number(data.total_count) > 100) {
    throw new PullRequestError("status_observation_incomplete");
  }
  const statuses = new Map<string, string>();
  for (const item of data.statuses) {
    const status = object(item, "malformed_status");
    if (typeof status.context !== "string" || typeof status.status !== "string") throw new PullRequestError("malformed_status");
    if (!statuses.has(status.context)) statuses.set(status.context, status.status);
  }

