import { test } from "vitest";
import assert from "node:assert/strict";
import { requestExactMerge, type PullRequestAdapter, type PullRequestObservation, PullRequestError } from "./contract.js";

const sha = "a".repeat(40);
const base = "b".repeat(40);
const repository = { provider: "other", instanceId: "fixture", nativeId: "opaque/repo" };
const observation: PullRequestObservation = {
  repository, nativeId: "opaque-pr", head: { repository, ref: "refs/heads/work", revision: sha },
  base: { repository, ref: "refs/heads/main", revision: base }, state: "open", draft: false,
  mergeable: true, mergeStrategy: "fast-forward-only", requiredChecks: [], requiredApprovals: 1,
  reviews: [{ nativeId: "review-1", actor: { nativeId: "person-1", login: "person", kind: "human" },
    decision: "approved", headRevision: sha, dismissed: false, stale: false, submittedAt: "2026-10-13T00:00:00Z" }],
  discussionCount: 0, providerRevision: "rev-1"
};

test("exact merge admits a current human approval and verifies the resulting candidate", async () => {
  let calls = 0;
  let current = observation;
  const adapter: PullRequestAdapter = {
    read: async () => current,
    mergeFastForward: async () => { calls++; current = { ...observation, state: "merged", mergedRevision: sha }; }
  };
  const result = await requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" });
  assert.equal(result.mergedRevision, sha);
  assert.equal(calls, 1);
});

test.each([
  ["head_moved", { head: { ...observation.head, revision: "c".repeat(40) } }],
  ["approval_missing", { reviews: [{ ...observation.reviews[0]!, stale: true }] }],
  ["approval_missing", { reviews: [{ ...observation.reviews[0]!, actor: { nativeId: "bot", login: "bot", kind: "bot" as const } }] }],
  ["required_checks_incomplete", { requiredChecks: [{ context: "build", state: "pending" as const }] }],
  ["merge_conflict", { mergeable: false }],
  ["draft_pr", { draft: true }]
])("exact merge rejects %s before a provider write", async (code, change) => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation, ...change }),
    mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === code);
  assert.equal(calls, 0);
});

test("ambiguous merge never becomes success without an authenticated merged observation", async () => {
  const adapter: PullRequestAdapter = { read: async () => observation,
    mergeFastForward: async () => { throw new Error("timeout"); } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === "merge_outcome_unknown");
});

test("a later dismissed decision revokes an earlier approval from the same Human", async () => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation, reviews: [
    observation.reviews[0]!, { ...observation.reviews[0]!, nativeId: "review-2", dismissed: true,
      submittedAt: "2026-10-13T01:00:00Z" }
  ] }), mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === "approval_missing");
  assert.equal(calls, 0);
});

test("a moved base revision denies merge even when its ref is unchanged", async () => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation,
    base: { ...observation.base, revision: "c".repeat(40) } }), mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only",
    requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === "base_moved");
  assert.equal(calls, 0);
});

test("conflicting reviews with the same timestamp fail closed for opaque provider IDs", async () => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation, reviews: [
    { ...observation.reviews[0]!, nativeId: "alpha" },
    { ...observation.reviews[0]!, nativeId: "omega", decision: "changes_requested" }
  ] }), mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only",
    requiredHumanActorId: "person-1" }), (error: unknown) =>
    error instanceof PullRequestError && error.code === "approval_ambiguous");
  assert.equal(calls, 0);
});

