1	import assert from "node:assert/strict";
2	import { execFile } from "node:child_process";
3	import { randomUUID } from "node:crypto";
4	import { mkdtemp, rm } from "node:fs/promises";
5	import { tmpdir } from "node:os";
6	import { join } from "node:path";
7	import { promisify } from "node:util";
8	import { test } from "vitest";
9	import { readCiCredential } from "../ci/credential.js";
10	import { GiteaGitPushPort } from "../hosting/gitPush.js";
11	import { GiteaHostingAdapter } from "../hosting/gitea.js";
12	import { trustedOwnerGitEnvironment } from "../gitExecution.js";
13	import { GiteaPullRequestAdapter } from "./gitea.js";
14	
15	const git = promisify(execFile);
16	const config = {
17	  baseUrl: process.env.PI_GITEA_PR_TEST_BASE_URL,
18	  owner: process.env.PI_GITEA_PR_TEST_OWNER,
19	  repository: process.env.PI_GITEA_PR_TEST_REPOSITORY,
20	  repositoryId: process.env.PI_GITEA_PR_TEST_REPOSITORY_ID,
21	  gitUsername: process.env.PI_GITEA_PR_TEST_GIT_USERNAME,
22	  hostingCredentialRef: process.env.PI_GITEA_PR_TEST_HOSTING_CREDENTIAL_REF,
23	  prCredentialRef: process.env.PI_GITEA_PR_TEST_PR_CREDENTIAL_REF
24	};
25	const ready = Object.values(config).every((value) => typeof value === "string" && value.length > 0) &&
26	  process.env.PI_GITEA_PR_TEST_DISPOSABLE_REPOSITORY === "1" && !!process.env.CREDENTIALS_DIRECTORY;
27	
28	/** Opt-in provider check; mutates only uniquely named branches in a disposable repository. */
29	test.skipIf(!ready)("real Gitea draft, readiness and exact fast-forward merge", async () => {
30	  assert.equal(new URL(config.baseUrl!).protocol, "https:");
31	  const root = await mkdtemp(join(tmpdir(), "relayview-pr-real-"));
32	  const suffix = randomUUID();
33	  const baseRef = `refs/heads/relayview/pr-smoke/base/${suffix}`;
34	  const headRef = `refs/heads/relayview/pr-smoke/head/${suffix}`;
35	  const hostToken = () => readCiCredential(config.hostingCredentialRef!);
36	  const prToken = () => readCiCredential(config.prCredentialRef!);
37	  const port = new GiteaGitPushPort({ sourceWorktree: root, baseUrl: config.baseUrl!,
38	    owner: config.owner!, repository: config.repository!, gitUsername: config.gitUsername!, token: hostToken });
39	  const adapter = new GiteaPullRequestAdapter({ instanceId: "pr-real-smoke", baseUrl: config.baseUrl!,
40	    owner: config.owner!, name: config.repository!, token: prToken });
41	  let base: string | undefined;
42	  let head: string | undefined;
43	  let prId: string | undefined;
44	  let mergedConfirmed = false;
45	  try {
46	    const env = trustedOwnerGitEnvironment();
47	    await git("git", ["init", "--quiet", root], { env });
48	    const commit = async (message: string) => git("git", ["-C", root, "-c", "core.hooksPath=/dev/null",
49	      "-c", "user.name=RelayView smoke", "-c", "user.email=pr-smoke@example.invalid",
50	      "commit", "--allow-empty", "--quiet", "-m", message], { env });
51	    await commit("PR smoke base");
52	    base = (await git("git", ["-C", root, "rev-parse", "HEAD"], { env })).stdout.trim();
53	    await commit("PR smoke head");
54	    head = (await git("git", ["-C", root, "rev-parse", "HEAD"], { env })).stdout.trim();
55	    const repository = await adapter.repository();
56	    assert.equal(repository.nativeId, config.repositoryId);
57	    await port.push(baseRef, base, null);
58	    await port.push(headRef, head, null);
59	    const draft = await adapter.createDraft(repository, headRef, baseRef, head, `PR smoke ${suffix}`);
60	    prId = draft.nativeId;
61	    assert.equal(draft.draft, true);
62	    await assert.rejects(adapter.mergeFastForward(repository, prId, head),
63	      "a draft must be denied by the provider before readiness");
64	    const readyPr = await adapter.markReady(repository, prId, head);
65	    assert.equal(readyPr.draft, false);
66	    await adapter.mergeFastForward(repository, prId, head);
67	    const merged = await adapter.read(repository, prId);
68	    assert.equal(merged?.state, "merged");
69	    assert.equal(merged?.mergedRevision, head);
70	    mergedConfirmed = true;
71	  } finally {
72	    try {
73	      const repository = await adapter.repository();
74	      if (prId) {
75	        const observed = await adapter.read(repository, prId);
76	        if (observed?.state === "open") {
77	          const token = await prToken();
78	          const url = new URL(`api/v1/repos/${encodeURIComponent(config.owner!)}/${encodeURIComponent(config.repository!)}/pulls/${prId}`,
79	            config.baseUrl!);
80	          const closed = await fetch(url, { method: "PATCH", headers: { Authorization: `token ${token}`,
81	            "Content-Type": "application/json" }, body: JSON.stringify({ state: "closed" }), redirect: "error" });
82	          assert.equal(closed.ok, true, "disposable smoke PR needs manual cleanup");
83	        }
84	      }
85	      for (const [ref, expected] of [[headRef, head], [baseRef, mergedConfirmed ? head : base]] as const) {
86	        if (!expected) continue;
87	        const observed = await portBranch(ref);
88	        if (!observed) continue;
89	        assert.equal(observed, expected, `disposable smoke branch ${ref} moved; inspect before cleanup`);
90	        await port.deleteExact(ref, expected);
91	      }
92	    } finally { await rm(root, { recursive: true, force: true }); }
93	  }
94	
95	  async function portBranch(ref: string): Promise<string | undefined> {
96	    const repository = await adapter.repository();
97	    return (await new GiteaHostingAdapter({ instanceId: "pr-real-smoke",
98	      baseUrl: config.baseUrl!, owner: config.owner!, name: config.repository!, token: hostToken })
99	      .branch(repository, ref))?.revision;
100	  }
101	}, 180_000);
