import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";
import { test } from "vitest";
import { readCiCredential } from "../ci/credential.js";
import { GiteaGitPushPort } from "../hosting/gitPush.js";
import { GiteaHostingAdapter } from "../hosting/gitea.js";
import { trustedOwnerGitEnvironment } from "../gitExecution.js";
import { GiteaPullRequestAdapter } from "./gitea.js";

const git = promisify(execFile);
const config = {
  baseUrl: process.env.PI_GITEA_PR_TEST_BASE_URL,
  owner: process.env.PI_GITEA_PR_TEST_OWNER,
  repository: process.env.PI_GITEA_PR_TEST_REPOSITORY,
  repositoryId: process.env.PI_GITEA_PR_TEST_REPOSITORY_ID,
  gitUsername: process.env.PI_GITEA_PR_TEST_GIT_USERNAME,
  hostingCredentialRef: process.env.PI_GITEA_PR_TEST_HOSTING_CREDENTIAL_REF,
  prCredentialRef: process.env.PI_GITEA_PR_TEST_PR_CREDENTIAL_REF
};
const ready = Object.values(config).every((value) => typeof value === "string" && value.length > 0) &&
  process.env.PI_GITEA_PR_TEST_DISPOSABLE_REPOSITORY === "1" && !!process.env.CREDENTIALS_DIRECTORY;

/** Opt-in provider check; mutates only uniquely named branches in a disposable repository. */
test.skipIf(!ready)("real Gitea draft, readiness and exact fast-forward merge", async () => {
  assert.equal(new URL(config.baseUrl!).protocol, "https:");
  const root = await mkdtemp(join(tmpdir(), "relayview-pr-real-"));
  const suffix = randomUUID();
  const baseRef = `refs/heads/relayview/pr-smoke/base/${suffix}`;
  const headRef = `refs/heads/relayview/pr-smoke/head/${suffix}`;
  const hostToken = () => readCiCredential(config.hostingCredentialRef!);
  const prToken = () => readCiCredential(config.prCredentialRef!);
  const port = new GiteaGitPushPort({ sourceWorktree: root, baseUrl: config.baseUrl!,
    owner: config.owner!, repository: config.repository!, gitUsername: config.gitUsername!, token: hostToken });
  const adapter = new GiteaPullRequestAdapter({ instanceId: "pr-real-smoke", baseUrl: config.baseUrl!,
    owner: config.owner!, name: config.repository!, token: prToken });
  let base: string | undefined;
  let head: string | undefined;
  let prId: string | undefined;
  let mergedConfirmed = false;
  try {
    const env = trustedOwnerGitEnvironment();
    await git("git", ["init", "--quiet", root], { env });
    const commit = async (message: string) => git("git", ["-C", root, "-c", "core.hooksPath=/dev/null",
      "-c", "user.name=RelayView smoke", "-c", "user.email=pr-smoke@example.invalid",
      "commit", "--allow-empty", "--quiet", "-m", message], { env });
    await commit("PR smoke base");
    base = (await git("git", ["-C", root, "rev-parse", "HEAD"], { env })).stdout.trim();
    await commit("PR smoke head");
    head = (await git("git", ["-C", root, "rev-parse", "HEAD"], { env })).stdout.trim();
    const repository = await adapter.repository();
    assert.equal(repository.nativeId, config.repositoryId);
    await port.push(baseRef, base, null);
    await port.push(headRef, head, null);
    const draft = await adapter.createDraft(repository, headRef, baseRef, head, `PR smoke ${suffix}`);
    prId = draft.nativeId;
    assert.equal(draft.draft, true);
    await assert.rejects(adapter.mergeFastForward(repository, prId, head),
      "a draft must be denied by the provider before readiness");
    const readyPr = await adapter.markReady(repository, prId, head);
    assert.equal(readyPr.draft, false);
    await adapter.mergeFastForward(repository, prId, head);
    const merged = await adapter.read(repository, prId);
    assert.equal(merged?.state, "merged");
    assert.equal(merged?.mergedRevision, head);
    mergedConfirmed = true;
  } finally {
    try {
      const repository = await adapter.repository();
      if (prId) {
        const observed = await adapter.read(repository, prId);
        if (observed?.state === "open") {
          const token = await prToken();
          const url = new URL(`api/v1/repos/${encodeURIComponent(config.owner!)}/${encodeURIComponent(config.repository!)}/pulls/${prId}`,
            config.baseUrl!);
          const closed = await fetch(url, { method: "PATCH", headers: { Authorization: `token ${token}`,
            "Content-Type": "application/json" }, body: JSON.stringify({ state: "closed" }), redirect: "error" });
          assert.equal(closed.ok, true, "disposable smoke PR needs manual cleanup");
        }
      }
      for (const [ref, expected] of [[headRef, head], [baseRef, mergedConfirmed ? head : base]] as const) {
        if (!expected) continue;
        const observed = await portBranch(ref);
        if (!observed) continue;
        assert.equal(observed, expected, `disposable smoke branch ${ref} moved; inspect before cleanup`);
        await port.deleteExact(ref, expected);
      }
    } finally { await rm(root, { recursive: true, force: true }); }
  }

  async function portBranch(ref: string): Promise<string | undefined> {
    const repository = await adapter.repository();
    return (await new GiteaHostingAdapter({ instanceId: "pr-real-smoke",
      baseUrl: config.baseUrl!, owner: config.owner!, name: config.repository!, token: hostToken })
      .branch(repository, ref))?.revision;
  }
}, 180_000);

