test("Gitea observation distinguishes required and advisory status, Human and bot reviews", async () => {
  const { adapter, calls } = fixture();
  const repository = await adapter.repository();
  const result = await adapter.read(repository, "7");
  assert.equal(result?.head.revision, head);
  assert.deepEqual(result?.requiredChecks, [{ context: "build", state: "success" }]);
  assert.deepEqual(result?.advisoryChecks, [{ context: "advisory", state: "failure" }]);
  assert.equal(result?.reviews[0]?.actor.kind, "human");
  assert.equal(result?.reviews[1]?.actor.kind, "bot");
  assert.equal(result?.reviews[2]?.decision, "pending");
  assert.equal(result?.reviews[2]?.stale, true);
  assert.equal(result?.discussionCount, 2);
  assert.equal(calls.some((call) => call.path.includes("/issues/") || call.path.includes("/actions/")), false);
});

test("Gitea rejects a PR whose native repository identity differs from its binding", async () => {
  const { adapter } = fixture({ head: { ref: "work", sha: head, repo: { ...repo, id: 13 } } });
  await assert.rejects(adapter.read(await adapter.repository(), "7"),
    (error: unknown) => error instanceof PullRequestError && error.code === "repository_mismatch");
});

test("Gitea merge dispatch sends exact head and never forces or queues merge", async () => {
  const { adapter, calls } = fixture();
  await adapter.mergeFastForward(await adapter.repository(), "7", head);
  assert.deepEqual(calls.at(-1)?.body, { do: "fast-forward-only", head_commit_id: head,
    force_merge: false, merge_when_checks_succeed: false, delete_branch_after_merge: false });
});

